@js:
sort=[];
push=(title,url,type)=>{
		return sort.push(JSON.stringify({
				title: title,
				url: url,
				style: {
						layout_flexGrow: 1,
						layout_flexBasisPercent: type
					}
			}))
	}
push("热门小说", `http://app.1001p.com/api/book/bookRankQuery,{"body":{"value":{"rankType":"3","pageSize":"20","pageNum":"{{page}\}"}},"method":"POST"}`, 0.4);
push("完本小说", `http://app.1001p.com/api/book/bookList,{"body":{"value":{"pageSize":"20","pageNum":"{{page}\}","endStatus":"1"}},"method":"POST"}`, 0.4);
