@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	push("分类", null, 1, 1);
	fl=[["全部","all"],["玄幻","xuanhuan"],["奇幻","qihuan"],["武侠","wuxia"],["仙侠","xianxia"],["都市","dushi"],["历史","lishi"],["军事","junshi"],["游戏","youxi"],["竞技","jingji"],["科幻","kehuan"],["灵异","lingyi"],["同人","tongren"],["女生","nvsheng"],["其他","qita"]];
fl.map(([title,uri],index)=>{
	url= `/sort/${uri}<,/{{page}}>.html`;
	if(index+1 <= fl.length - fl.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}  	
    })

push("完本",  `/over/<,{{page}}.html>`, 1, 1);

 push("榜单", null, 1, 1);
 bd = [["总点击","allvisit"],["月点击","monthvisit"],["周点击","weekvisit"],["日点击","dayvisit"],["总推荐","votenum"],,["总收藏","marknum"],["下载","downnum"],["入库","postdate"],["最近","lastupdate"]];
	  bd.map(([title,uri],index)=>{
	    url= `/top/${uri}<,/{{page}}>.html`;
	if(index+1 <= bd.length - bd.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);} 	
    	});
JSON.stringify(sort);

