script.-1@html
<js>
try{ uri=result.match(/get\('([^,]*)'/)[1]; }
catch(e){
	id=baseUrl.match(/(\d+)\/(\d*)/);
  uri='/novelsearch/reader/transcode/siteid/'+id[1]+'/'+id[2]+'/';
 }
 burl=source.getKey().match(/([^#]*)/)[1];
 url=burl+uri;
 res=java.ajax(url);
 content=JSON.parse(res).info;
</js>

